\begin{tikzpicture}
\begin{axis}[
    width=0.68\textwidth,
    height=0.42\textwidth,
    xmin=-1.4, xmax=1.4,
    ymin=-0.3, ymax=1.35,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(J(x)\)},
    xtick={-1,0,1},
    ytick={0,1},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=-1.35:-0.04, samples=2] {0};
\addplot[thick, domain=0:1.35, samples=2] {1};
\addplot[only marks, mark=o, mark size=3pt, thick] coordinates {(0,0)};
\addplot[only marks, mark=*, mark size=2.5pt] coordinates {(0,1)};
\node[anchor=south east] at (axis cs:-0.15,0.12) {left target \(0\)};
\node[anchor=north west] at (axis cs:0.22,0.88) {right target \(1\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.70\textwidth,
    height=0.46\textwidth,
    xmin=-1.1, xmax=1.1,
    ymin=0, ymax=30,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-1,0,1},
    ytick={10,20,30},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=-1:-0.19, samples=120] {1/(x^2)};
\addplot[thick, domain=0.19:1, samples=120] {1/(x^2)};
\draw[dashed, thick] (axis cs:0,0) -- (axis cs:0,30);
\node[anchor=west] at (axis cs:0.12,12) {\(x=0\)};
\end{axis}
\end{tikzpicture}

